import AppKit
import Foundation
import UniformTypeIdentifiers

struct ClipboardImage {
    struct Representation {
        let type: NSPasteboard.PasteboardType
        let data: Data
    }

    let data: Data
    let pasteboardType: NSPasteboard.PasteboardType
    /// Compatibility rasters generated by ClipDeck (PNG/TIFF, or a PDF's first
    /// page). They can be dropped under memory pressure and rebuilt on restore.
    let derivedRepresentations: [Representation]
    /// Derived types that were dropped to save memory.
    let droppedDerivedTypes: [NSPasteboard.PasteboardType]
    let pixelWidth: Int
    let pixelHeight: Int
    let fingerprint: Data
    let thumbnail: NSImage
    let preview: NSImage
    let renderingByteCount: Int
    let textRepresentation: String?

    init?(processed: ProcessedClipboardImage, textRepresentation: String? = nil) {
        guard let thumbnail = NSImage(data: processed.thumbnailData) else {
            return nil
        }

        let pasteboardType = NSPasteboard.PasteboardType(processed.typeIdentifier)
        self.init(
            data: processed.data,
            pasteboardType: pasteboardType,
            derivedRepresentations: Self.orderedDerivedTypes(processed.additionalRepresentations.keys)
                .filter { $0 != processed.typeIdentifier }
                .compactMap { type in
                    processed.additionalRepresentations[type].map {
                        Representation(type: NSPasteboard.PasteboardType(type), data: $0)
                    }
                },
            droppedDerivedTypes: [],
            pixelWidth: processed.pixelWidth,
            pixelHeight: processed.pixelHeight,
            fingerprint: processed.fingerprint,
            thumbnail: thumbnail,
            preview: processed.previewData.flatMap(NSImage.init(data:)) ?? thumbnail,
            renderingByteCount: processed.thumbnailData.count + (processed.previewData?.count ?? 0),
            textRepresentation: textRepresentation
        )
    }

    private init(
        data: Data,
        pasteboardType: NSPasteboard.PasteboardType,
        derivedRepresentations: [Representation],
        droppedDerivedTypes: [NSPasteboard.PasteboardType],
        pixelWidth: Int,
        pixelHeight: Int,
        fingerprint: Data,
        thumbnail: NSImage,
        preview: NSImage,
        renderingByteCount: Int,
        textRepresentation: String?
    ) {
        self.data = data
        self.pasteboardType = pasteboardType
        self.derivedRepresentations = derivedRepresentations
        self.droppedDerivedTypes = droppedDerivedTypes
        self.pixelWidth = pixelWidth
        self.pixelHeight = pixelHeight
        self.fingerprint = fingerprint
        self.thumbnail = thumbnail
        self.preview = preview
        self.renderingByteCount = renderingByteCount
        self.textRepresentation = textRepresentation
    }

    /// PNG first: it is compact and what web and Electron apps look for; TIFF
    /// follows for older AppKit, Qt, and Java readers.
    static func orderedDerivedTypes(_ types: some Collection<String>) -> [String] {
        func priority(_ type: String) -> Int {
            switch type {
            case UTType.png.identifier: return 0
            case UTType.tiff.identifier: return 1
            default: return 2
            }
        }
        return types.sorted { priority($0) == priority($1) ? $0 < $1 : priority($0) < priority($1) }
    }

    var dimensionsText: String {
        guard pixelWidth > 0, pixelHeight > 0 else {
            return L10n.string("未知尺寸")
        }

        return "\(pixelWidth)×\(pixelHeight)"
    }

    var isPDF: Bool { pasteboardType.rawValue == UTType.pdf.identifier }

    var storageByteCount: Int {
        derivedRepresentations.reduce(renderingByteCount + data.count) { $0 + $1.data.count }
    }

    func withoutDerivedRepresentations() -> ClipboardImage {
        ClipboardImage(
            data: data,
            pasteboardType: pasteboardType,
            derivedRepresentations: [],
            droppedDerivedTypes: droppedDerivedTypes + derivedRepresentations.map(\.type),
            pixelWidth: pixelWidth,
            pixelHeight: pixelHeight,
            fingerprint: fingerprint,
            thumbnail: thumbnail,
            preview: preview,
            renderingByteCount: renderingByteCount,
            textRepresentation: textRepresentation
        )
    }
}

/// One original pasteboard item. Values are immutable snapshots, never lazy
/// providers. Entries keep the writer's type order, which receiving apps treat
/// as preference order (richest first).
struct ClipboardRepresentationItem: Sendable, Equatable {
    struct Entry: Sendable, Equatable {
        let type: String
        let data: Data
        /// A compatibility raster generated by ClipDeck from the item's image.
        /// It may be dropped to save memory and is rebuilt when restoring.
        var isRebuildable = false
    }

    let entries: [Entry]
    /// Rebuildable types that were dropped to save memory.
    let droppedRebuildableTypes: [String]

    init(entries: [Entry], droppedRebuildableTypes: [String] = []) {
        var seen = Set<String>()
        self.entries = entries.filter { seen.insert($0.type).inserted }
        self.droppedRebuildableTypes = droppedRebuildableTypes
    }

    func data(forType type: String) -> Data? {
        entries.first { $0.type == type }?.data
    }

    func contains(type: String) -> Bool {
        entries.contains { $0.type == type }
    }

    var byteCount: Int { entries.reduce(0) { $0 + $1.data.count } }

    var hasRebuildableData: Bool { entries.contains(where: \.isRebuildable) }

    func droppingRebuildableData() -> ClipboardRepresentationItem {
        ClipboardRepresentationItem(
            entries: entries.filter { !$0.isRebuildable },
            droppedRebuildableTypes: droppedRebuildableTypes
                + entries.filter(\.isRebuildable).map(\.type)
        )
    }

    /// Compares what the source app provided, ignoring ClipDeck's rebuildable rasters.
    func hasSameSourceData(as other: ClipboardRepresentationItem) -> Bool {
        entries.filter { !$0.isRebuildable } == other.entries.filter { !$0.isRebuildable }
    }
}

struct ClipboardFileReference {
    let url: URL
    let displayName: String
    let isDirectory: Bool

    init(url: URL) {
        let standardizedURL = url.standardizedFileURL
        self.url = standardizedURL
        self.displayName = standardizedURL.lastPathComponent.isEmpty
            ? standardizedURL.path
            : standardizedURL.lastPathComponent
        // This is deliberately only a URL hint. Reading resource metadata or
        // requesting file icons here can block the main actor for network,
        // cloud, or disconnected-volume URLs while the clipboard is polled.
        self.isDirectory = standardizedURL.hasDirectoryPath
    }

    var systemImageName: String {
        isDirectory ? "folder" : "doc"
    }
}

struct ClipboardFileList {
    let references: [ClipboardFileReference]

    init?(urls: [URL]) {
        var seenURLs = Set<String>()
        let uniqueURLs = urls.compactMap { url -> URL? in
            guard url.isFileURL else {
                return nil
            }

            let standardizedURL = url.standardizedFileURL
            guard seenURLs.insert(standardizedURL.absoluteString).inserted else {
                return nil
            }
            return standardizedURL
        }
        guard !uniqueURLs.isEmpty else {
            return nil
        }

        self.references = uniqueURLs.map(ClipboardFileReference.init(url:))
    }

    var urls: [URL] {
        references.map(\.url)
    }

    fileprivate var comparisonKey: [String] {
        references.map { $0.url.absoluteString }.sorted()
    }
}

struct ClipboardItem: Identifiable {
    enum Content {
        case text(String)
        case image(ClipboardImage)
        case files(ClipboardFileList)
    }

    let id: UUID
    let content: Content
    let parts: [Content]
    let originalItems: [ClipboardRepresentationItem]
    let captureNote: String?
    let capturedAt: Date

    /// Kept for source compatibility with existing callers.
    var copiedAt: Date { capturedAt }

    /// Cached display/search values avoid rebuilding large strings on each SwiftUI update.
    let preview: String
    let menuTitle: String
    let searchableText: String

    /// Relative to now, so a long-running session can tell days apart.
    var timestampText: String { Self.timestampText(for: capturedAt) }

    init(id: UUID = UUID(), text: String, copiedAt: Date = .now) {
        self.init(id: id, content: .text(text), copiedAt: copiedAt)
    }

    init(id: UUID = UUID(), image: ClipboardImage, copiedAt: Date = .now) {
        self.init(id: id, content: .image(image), copiedAt: copiedAt)
    }

    init(id: UUID = UUID(), files: ClipboardFileList, copiedAt: Date = .now) {
        self.init(id: id, content: .files(files), copiedAt: copiedAt)
    }

    init(id: UUID = UUID(), content: Content, copiedAt: Date = .now) {
        self.init(id: id, parts: [content], originalItems: [], copiedAt: copiedAt)
    }

    init(
        id: UUID = UUID(),
        parts: [Content],
        originalItems: [ClipboardRepresentationItem] = [],
        captureNote: String? = nil,
        copiedAt: Date = .now
    ) {
        precondition(!parts.isEmpty)
        let content = parts[0]
        self.id = id
        self.content = content
        self.parts = parts
        self.originalItems = originalItems
        self.captureNote = captureNote
        self.capturedAt = copiedAt

        let preview: String
        switch content {
        case .text(let text):
            let normalized = text
                .split(whereSeparator: { $0.isWhitespace })
                .joined(separator: " ")
            preview = normalized.isEmpty
                ? L10n.string("空白文本")
                : normalized.truncated(to: 140)
        case .image(let image):
            preview = image.isPDF ? "PDF · " + image.dimensionsText : L10n.string("图片 · %@", image.dimensionsText)
        case .files(let files):
            if files.references.count == 1, let file = files.references.first {
                preview = file.isDirectory
                    ? L10n.string("文件夹 · %@", file.displayName)
                    : L10n.string("文件 · %@", file.displayName)
            } else {
                preview = L10n.string("%@ 等 %lld 个文件", files.references[0].displayName, Int64(files.references.count))
            }
        }

        let groupedPreview = parts.count > 1
            ? L10n.string("组合内容 · %lld 项", Int64(parts.count)) + " · " + preview
            : preview
        self.preview = groupedPreview
        self.menuTitle = groupedPreview.truncated(to: 30)
        // A line break keeps search terms from matching across part boundaries.
        self.searchableText = Self.normalizedSearchText(
            parts.map(Self.searchSource(for:)).joined(separator: "\n")
        )
    }

    private static func searchSource(for content: Content) -> String {
        switch content {
        case .text(let text):
            return text
        case .image(let image):
            // Both languages, so "image" and "图片" work whatever the UI language.
            return "图片 图像 image \(image.isPDF ? "PDF " : "")\(image.dimensionsText) \(image.textRepresentation ?? "")"
        case .files(let files):
            return files.references
                .flatMap { [$0.displayName, $0.url.path] }
                .joined(separator: " ")
                + " 文件 文件夹 file folder"
        }
    }

    var isMultiPart: Bool { parts.count > 1 }

    var hasRichText: Bool {
        let richTypes = [
            NSPasteboard.PasteboardType.rtf.rawValue,
            NSPasteboard.PasteboardType.rtfd.rawValue,
            NSPasteboard.PasteboardType.html.rawValue
        ]
        return originalItems.contains { item in richTypes.contains(where: item.contains(type:)) }
    }

    var plainText: String? {
        let values = parts.compactMap { part -> String? in
            switch part {
            case .text(let value): return value
            case .image(let image): return image.textRepresentation
            case .files: return nil
            }
        }
        return values.isEmpty ? nil : values.joined(separator: "\n")
    }

    /// Replay snapshots share image Data buffers with the display parts. Count
    /// those encodings once, plus separately owned text and preview buffers.
    var storageByteCount: Int {
        let hasReplaySnapshot = !originalItems.isEmpty
        return originalItems.reduce(0) { $0 + $1.byteCount } + parts.reduce(0) { count, part in
            switch part {
            case .text(let text): return count + text.utf8.count
            case .image(let image):
                return count + (hasReplaySnapshot ? image.renderingByteCount : image.storageByteCount)
            case .files(let files):
                return count + files.urls.reduce(0) { $0 + $1.absoluteString.utf8.count }
            }
        }
    }

    /// Whether ClipDeck-generated compatibility rasters can be released.
    var hasRebuildableData: Bool {
        originalItems.contains(where: \.hasRebuildableData) || parts.contains { part in
            if case .image(let image) = part { return !image.derivedRepresentations.isEmpty }
            return false
        }
    }

    /// The same history entry without ClipDeck's compatibility rasters. Both the
    /// replay snapshot and the display part drop them, so the memory is actually
    /// released; they are rebuilt from the original image when copied again.
    func droppingRebuildableData() -> ClipboardItem {
        ClipboardItem(
            id: id,
            parts: parts.map { part in
                if case .image(let image) = part { return .image(image.withoutDerivedRepresentations()) }
                return part
            },
            originalItems: originalItems.map { $0.droppingRebuildableData() },
            captureNote: captureNote,
            copiedAt: capturedAt
        )
    }

    var text: String? {
        guard case .text(let text) = content else {
            return nil
        }

        return text
    }

    var image: ClipboardImage? {
        guard case .image(let image) = content else {
            return nil
        }

        return image
    }

    var files: ClipboardFileList? {
        guard case .files(let files) = content else {
            return nil
        }

        return files
    }

    var localizedContentType: String {
        if isMultiPart { return L10n.string("组合内容") }
        if image?.isPDF == true { return "PDF" }
        switch content {
        case .text:
            return L10n.string("文字")
        case .image:
            return L10n.string("图片")
        case .files:
            return L10n.string("文件")
        }
    }

    var systemImageName: String {
        if isMultiPart { return "square.stack.3d.up" }
        if image?.isPDF == true { return "doc.richtext" }
        switch content {
        case .text:
            return "doc.text"
        case .image:
            return "photo"
        case .files:
            return "doc.on.doc"
        }
    }

    var localizedCopyActionTitle: String {
        if isMultiPart || hasRichText || image?.isPDF == true {
            return L10n.string("复制完整内容到剪贴板")
        }
        switch content {
        case .text:
            return L10n.string("复制文字到剪贴板")
        case .image:
            return L10n.string("复制图片到剪贴板")
        case .files:
            return L10n.string("复制文件到剪贴板")
        }
    }

    var localizedCopiedAnnouncement: String {
        if isMultiPart || hasRichText || image?.isPDF == true {
            return L10n.string("完整内容已复制")
        }
        switch content {
        case .text:
            return L10n.string("文字已复制")
        case .image:
            return L10n.string("图片已复制")
        case .files:
            return L10n.string("文件已复制")
        }
    }

    func hasSameContent(as other: ClipboardItem) -> Bool {
        guard parts.count == other.parts.count else { return false }
        // Preserve two equal-looking text snippets with different formatting.
        let urlType = NSPasteboard.PasteboardType.URL.rawValue
        let containsTypedURL = originalItems.contains { $0.contains(type: urlType) }
        let otherContainsTypedURL = other.originalItems.contains { $0.contains(type: urlType) }
        if hasRichText || other.hasRichText || containsTypedURL || otherContainsTypedURL {
            guard originalItems.count == other.originalItems.count,
                  zip(originalItems, other.originalItems).allSatisfy({ $0.hasSameSourceData(as: $1) }) else {
                return false
            }
        }
        return zip(parts, other.parts).allSatisfy { Self.samePart($0.0, $0.1) }
    }

    private static func samePart(_ leftPart: Content, _ rightPart: Content) -> Bool {
        switch (leftPart, rightPart) {
        case (.text(let left), .text(let right)):
            return left == right
        case (.image(let left), .image(let right)):
            return left.data.count == right.data.count
                && left.fingerprint == right.fingerprint
                && left.data == right.data
                && left.textRepresentation == right.textRepresentation
        case (.files(let left), .files(let right)):
            return left.comparisonKey == right.comparisonKey
        default:
            return false
        }
    }

    /// Case-, diacritic-, and width-insensitive, then NFC so equivalent text
    /// always has the same UTF-8 bytes for searching.
    static func normalizedSearchText(_ text: String) -> String {
        text.folding(
            options: [.caseInsensitive, .diacriticInsensitive, .widthInsensitive],
            locale: .current
        ).precomposedStringWithCanonicalMapping
    }

    static func timestampText(
        for date: Date,
        relativeTo now: Date = .now,
        calendar: Calendar = .current
    ) -> String {
        let time = date.formatted(date: .omitted, time: .shortened)
        if calendar.isDate(date, inSameDayAs: now) {
            return time
        }
        if let yesterday = calendar.date(byAdding: .day, value: -1, to: now),
           calendar.isDate(date, inSameDayAs: yesterday) {
            return L10n.string("昨天 %@", time)
        }
        let day = calendar.isDate(date, equalTo: now, toGranularity: .year)
            ? date.formatted(.dateTime.month(.abbreviated).day())
            : date.formatted(.dateTime.year().month(.abbreviated).day())
        return "\(day) \(time)"
    }
}
